// Writes the Firebase web config into src/environments/firebase.env.ts before every build, serve
// and test run. The values come from the process environment (Vercel) or from .env.local; the
// generated file is not committed. A missing value is reported at runtime by readFirebaseConfig().
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUTPUT = path.resolve(ROOT, 'src/environments/firebase.env.ts');
const LOCAL_FILE = path.resolve(ROOT, '.env.local');

const VARIABLES = [
  'FIREBASE_API_KEY',
  'FIREBASE_AUTH_DOMAIN',
  'FIREBASE_PROJECT_ID',
  'FIREBASE_STORAGE_BUCKET',
  'FIREBASE_MESSAGING_SENDER_ID',
  'FIREBASE_APP_ID',
];

function readLocalFile() {
  if (!existsSync(LOCAL_FILE)) {
    return {};
  }

  const values = {};

  for (const line of readFileSync(LOCAL_FILE, 'utf8').split(/\r?\n/)) {
    const match = /^\s*([\w.]+)\s*=\s*(.*?)\s*$/.exec(line);

    if (match !== null && !line.trimStart().startsWith('#')) {
      values[match[1]] = match[2].replaceAll(/^["']|["']$/g, '');
    }
  }

  return values;
}

const local = readLocalFile();

// The Vite version used the VITE_ prefix; both names are accepted.
const pick = (name) =>
  process.env[name] ?? process.env[`VITE_${name}`] ?? local[name] ?? local[`VITE_${name}`] ?? '';

const entries = VARIABLES.map((name) => `  ${name}: ${JSON.stringify(pick(name).trim())},`);

mkdirSync(path.dirname(OUTPUT), { recursive: true });
writeFileSync(
  OUTPUT,
  `// Generated by scripts/write-environment.mjs. Do not edit or commit.\nexport const FIREBASE_ENV: Readonly<Record<string, string>> = {\n${entries.join('\n')}\n};\n`,
);
